import { cp, mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { E2E_ROOT } from "./cli";

export const FIXTURE_DIR: string = resolve(E2E_ROOT, "fixture");
export const TMP_ROOT: string = resolve(E2E_ROOT, ".tmp");

/** Generated by a run, never part of the template. */
const IGNORED = new Set([
  "node_modules",
  "dist",
  ".scaffold",
  "typings",
]);

export interface Project {
  dir: string;
  read: (path: string) => Promise<string>;
  write: (path: string, content: string) => Promise<void>;
  at: (path: string) => string;
  cleanup: () => Promise<void>;
}

export async function createProject(name: string): Promise<Project> {
  await mkdir(TMP_ROOT, { recursive: true });
  const dir = await mkdtemp(join(TMP_ROOT, `${slug(name)}-`));

  await cp(FIXTURE_DIR, dir, {
    recursive: true,
    filter: source => !IGNORED.has(source.slice(FIXTURE_DIR.length + 1).split(/[/\\]/)[0]),
  });

  return {
    dir,
    read: path => readFile(join(dir, path), "utf-8"),
    write: (path, content) => writeFile(join(dir, path), content),
    at: path => join(dir, path),
    cleanup: async () => {
      await rm(dir, { recursive: true, force: true });
    },
  };
}

function slug(name: string): string {
  return name
    .toLowerCase()
    .replaceAll(/[^\da-z]+/g, "-")
    .replaceAll(/^-|-$/g, "")
    .slice(0, 40);
}
